226:   applySpec(spec = {}) {
227:     const run = this.run;
228:     const lines = [];
229:     if (!run) return lines;
230: 
231:     if (spec.gold) {
232:       run.gold = Math.max(0, run.gold + spec.gold);
233:       lines.push(`${spec.gold > 0 ? "Gain" : "Lose"} ${Math.abs(spec.gold)} gold.`);
234:     }
235:     if (spec.hp) {
236:       run.hp = Math.max(1, Math.min(run.maxHp, run.hp + spec.hp));
237:       lines.push(`${spec.hp > 0 ? "Heal" : "Lose"} ${Math.abs(spec.hp)} HP.`);
238:     }
239:     if (spec.heal) {
240:       run.hp = Math.min(run.maxHp, run.hp + spec.heal);
241:       lines.push(`Heal ${spec.heal} HP.`);
242:     }
243:     if (spec.healPct) {
244:       const amount = Math.ceil(run.maxHp * spec.healPct);
245:       run.hp = Math.min(run.maxHp, run.hp + amount);
246:       lines.push(`Heal ${amount} HP.`);
247:     }
248:     if (spec.maxHp) {
249:       run.maxHp = Math.max(10, run.maxHp + spec.maxHp);
250:       run.hp = Math.min(run.hp, run.maxHp);
251:       lines.push(`${spec.maxHp > 0 ? "Gain" : "Lose"} ${Math.abs(spec.maxHp)} max HP.`);
252:     }
253:     if (spec.strength) {
254:       run.strength = Math.max(0, run.strength + spec.strength);
255:       lines.push(`${spec.strength > 0 ? "Gain" : "Lose"} ${Math.abs(spec.strength)} Strength.`);
256:     }
257:     if (spec.crit) {
258:       run.crit = clamp(run.crit + spec.crit, 0, 0.75);
259:       lines.push(`Gain ${Math.round(spec.crit * 100)}% Crit.`);
260:     }
261:     if (spec.drawBonus) {
262:       run.drawCount += spec.drawBonus;
263:       lines.push(`Draw +${spec.drawBonus} card each turn.`);
264:     }
265:     if (spec.staminaBonus) {
266:       run.staminaMax += spec.staminaBonus;
267:       lines.push(`Gain +${spec.staminaBonus} max Stamina.`);
268:     }
269:     if (spec.tacoMax) {
270:       run.tacoMax += spec.tacoMax;
271:       lines.push(`Taco gains +${spec.tacoMax} max HP.`);
272:     }
273:     if (spec.tacoAttack) {
274:       run.tacoAttack += spec.tacoAttack;
275:       lines.push(`Taco gains +${spec.tacoAttack} bite damage.`);
276:     }
277:     if (spec.randomCard) {
278:       const key = this.randomCardKey(spec.randomCard);
279:       if (key) {
280:         this.addCard(key);
281:         lines.push(`Gained ${CARDS[key].name} (${spec.randomCard}).`);
282:       }
283:     }
284:     if (spec.randomCard2) {
285:       const key = this.randomCardKey(spec.randomCard2);
286:       if (key) {
287:         this.addCard(key);
288:         lines.push(`Gained ${CARDS[key].name} (${spec.randomCard2}).`);
289:       }
290:     }
291:     if (spec.randomUpgrade) {
292:       const candidates = run.deck.filter((c) => !c.upgraded);
293:       shuffle(candidates);
294:       const chosen = candidates.slice(0, spec.randomUpgrade);
295:       for (const card of chosen) {
296:         card.upgraded = true;
297:         lines.push(`Upgraded ${CARDS[card.key].name}.`);
298:       }
299:       if (!chosen.length) lines.push("Nothing left to upgrade.");
300:     }
301:     if (spec.randomCharm) {
302:       const key = this.randomAvailableCharm();
303:       if (key) {
304:         this.awardCharm(key);
305:         lines.push(`Gained charm: ${CHARMS[key].name}.`);
306:       } else {
307:         run.gold += 50;
308:         lines.push("All charms collected. Gained 50 gold instead.");
309:       }
310:     }
311:     if (spec.removeRandomCards) {
312:       const removable = [...run.deck];
313:       shuffle(removable);
314:       const removed = removable.slice(0, Math.min(spec.removeRandomCards, Math.max(0, run.deck.length - 4)));
315:       for (const card of removed) {
316:         this.removeCard(card.uid);
317:         lines.push(`Removed ${CARDS[card.key].name}.`);
318:       }
319:     }
320:     return lines;
321:   }
