325:   generateMap(act) {
326:     const shape = [[2], [1, 3], [0, 2, 4], [1, 3], [0, 2, 4], [1, 3], [0, 2, 4], [2]];
327:     const nodes = [];
328:     shape.forEach((cols, row) => {
329:       cols.forEach((col) => {
330:         let type = "battle";
331:         if (row === 0) type = "start";
332:         else if (row === 7) type = "boss";
333:         else type = this.rollNodeType(act, row);
334:         nodes.push({ id: `r${row}c${col}`, row, col, type, done: false });
335:       });
336:     });
337:     for (const required of ["shop", "event", "special"]) {
338:       if (!nodes.some((n) => n.type === required)) {
339:         const candidates = nodes.filter((n) => n.row >= 2 && n.row <= 6 && n.type !== "boss");
340:         if (candidates.length) pick(candidates).type = required;
341:       }
342:     }
343:     const map = { act, nodes };
344:     nodes.forEach((node) => {
345:       if (node.row === 7) {
346:         node.conn = [];
347:       } else if (node.row === 6) {
348:         node.conn = nodes.filter((n) => n.row === 7).map((n) => n.id);
349:       } else {
350:         node.conn = nodes
351:           .filter((n) => n.row === node.row + 1 && Math.abs(n.col - node.col) <= 1)
352:           .map((n) => n.id);
353:       }
354:     });
355:     return map;
356:   }
357: 
358:   rollNodeType(act, row) {
359:     if (row === 1) return "battle";
360:     const entries = [
361:       { value: "battle", weight: 34 },
362:       { value: "event", weight: 16 },
363:       { value: "shop", weight: 11 },
364:       { value: "special", weight: 10 },
365:       { value: "elite", weight: act === 3 ? 14 : 10 },
366:       { value: "rest", weight: 10 },
367:       { value: "treasure", weight: 7 },
368:     ];
369:     return weightedPick(entries);
370:   }
371: 
372:   getNode(id) {
373:     return this.run?.map.nodes.find((n) => n.id === id) || null;
374:   }
375: 
376:   availableFrom(node, map = this.run?.map) {
377:     if (!node || !map) return [];
378:     if (node.row >= 7) return [];
379:     if (node.row === 6) return map.nodes.filter((n) => n.row === 7);
380:     return map.nodes.filter((n) => n.row === node.row + 1 && Math.abs(n.col - node.col) <= 1);
381:   }
382: 
383:   enterNode(nodeId) {
384:     if (!this.run) return;
385:     if (!this.run.available.includes(nodeId)) return;
386:     const node = this.getNode(nodeId);
387:     if (!node || node.done) return;
388:     if (["battle", "elite", "boss"].includes(node.type)) {
389:       this.startBattle(node);
390:       return;
391:     }
392:     if (node.type === "shop") {
393:       this.openShop(node);
394:       return;
395:     }
396:     if (node.type === "event") {
397:       this.openEvent(node);
398:       return;
399:     }
400:     if (node.type === "special") {
401:       this.openSpecial(node);
402:       return;
403:     }
404:     if (node.type === "rest") {
405:       this.openRest(node);
406:       return;
407:     }
408:     if (node.type === "treasure") {
409:       this.openTreasure(node);
410:     }
411:   }
412: 
413:   endRun(kind) {
414:     if (!this.run || this.run.ended) return;
415:     this.run.ended = true;
416:     const run = this.run;
417:     const wasClear = kind === "clear";
418:     const ash = wasClear
419:       ? Math.floor(100 + run.roomsCleared * 2 + run.gold * 0.05 + this.meta.prestige * 15)
420:       : Math.max(12, Math.floor(10 + run.roomsCleared * 4 + (run.act - 1) * 16 + run.battlesWon * 3 + run.gold * 0.08));
421: 
422:     this.meta.ash += ash;
423:     this.meta.totalAsh += ash;
424:     this.meta.runs += 1;
425:     this.meta.sincePrestige += 1;
426:     this.meta.bestAct = Math.max(this.meta.bestAct, run.act);
427:     if (wasClear) {
428:       this.meta.clears += 1;
429:       this.meta.bossKills += 1;
430:     }
431:     this.saveMeta();
432:     this.combat = null;
433:     this.pending = {
434:       runSummary: {
435:         kind,
436:         ash,
437:         char: run.char,
438:         act: run.act,
439:         rooms: run.roomsCleared,
440:         gold: run.gold,
441:         deckSize: run.deck.length,
442:         charms: run.charms.length,
443:       },
444:     };
445:     this.screen = wasClear ? "runclear" : "gameover";
446:     this.emit();
447:   }
448: 
449:   returnFromRun() {
450:     this.run = null;
451:     this.combat = null;
452:     this.pending = null;
453:     this.setScreen("title");
454:   }
455: 
456:   prestigeLabel() {
457:     return PRESTIGE_STYLES[this.meta.prestige - 1] || null;
458:   }
459: }
