148:       if (card) combat.hand.push(card);
149:     }
150:   },
151: 
152:   selectCard(uid) {
153:     const combat = this.combat;
154:     if (!combat || combat.ended || combat.phase !== "player") return;
155:     if (combat.pendingCard === uid) {
156:       combat.pendingCard = null;
157:       this.emit();
158:       return;
159:     }
160:     const card = combat.hand.find((c) => c.uid === uid);
161:     if (!card) return;
162:     const def = CARDS[card.key];
163:     const cost = def.cost;
164:     if (combat.stamina < cost) {
165:       this.log("Not enough Stamina.", "bad");
166:       this.emit();
167:       return;
168:     }
169:     if (def.target === "enemy") {
170:       const taunts = this.tauntingEnemies();
171:       if (taunts.length) {
172:         this.playCard(uid, taunts[0].uid);
173:         return;
174:       }
175:       const alive = this.aliveEnemies();
176:       if (alive.length === 1) {
177:         this.playCard(uid, alive[0].uid);
178:         return;
179:       }
180:       combat.pendingCard = uid;
181:       this.emit();
182:       return;
183:     }
184:     this.playCard(uid);
185:   },
186: 
187:   cancelPending() {
188:     if (!this.combat) return;
189:     this.combat.pendingCard = null;
190:     this.emit();
191:   },
192: 
193:   playSelected(enemyUid) {
194:     const combat = this.combat;
195:     if (!combat?.pendingCard) return;
196:     const enemy = combat.enemies.find((e) => e.uid === enemyUid && e.alive);
197:     if (!enemy) return;
198:     const taunts = this.tauntingEnemies();
199:     if (taunts.length && !enemy.taunt) {
200:       this.log("The taunt holds your attention. Strike the one who demands it.", "bad");
201:       this.emit();
202:       return;
203:     }
204:     this.playCard(combat.pendingCard, enemyUid);
205:   },
206: 
207:   playCard(uid, targetUid) {
208:     const combat = this.combat;
209:     if (!combat || combat.ended || combat.phase !== "player") return;
210:     const index = combat.hand.findIndex((c) => c.uid === uid);
211:     if (index < 0) return;
212:     const card = combat.hand[index];
213:     const def = CARDS[card.key];
214:     if (combat.stamina < def.cost) {
215:       this.log("Not enough Stamina.", "bad");
216:       this.emit();
217:       return;
218:     }
219:     let target = null;
220:     if (def.target === "enemy") {
221:       const alive = this.aliveEnemies();
222:       if (!alive.length) return;
223:       target = combat.enemies.find((e) => e.uid === targetUid && e.alive) || alive[0];
224:     }
225: 
226:     combat.stamina -= def.cost;
227:     combat.hand.splice(index, 1);
228:     combat.pendingCard = null;
229:     this.log(`▸ ${def.name}${card.upgraded ? " +" : ""}`, "card");
230: 
231:     const effects = getEffects(card);
232:     for (const effect of effects) {
233:       this.resolveCardEffect(card, def, effect, target);
234:       if (!this.aliveEnemies().length) break;
235:       if (combat.player.hp <= 0) break;
236:     }
237: 
238:     if (def.exhaust) combat.exhaustPile.push(card);
239:     else combat.discardPile.push(card);
240: 
241:     if (!this.aliveEnemies().length) {
242:       this.finishVictory();
243:       return;
244:     }
245:     if (combat.player.hp <= 0) {
246:       this.playerDefeated();
247:       return;
248:     }
249:     this.emit();
250:   },
251: 
252:   resolveCardEffect(card, def, effect, target) {
253:     const combat = this.combat;
254:     const player = combat.player;
255:     const allTargets = def.target === "all";
256: 
257:     switch (effect.kind) {
258:       case "damage": {
259:         const targets = allTargets ? this.aliveEnemies() : target ? [target] : [];
260:         for (const enemy of targets) {
261:           if (!enemy.alive) continue;
262:           this.strikeEnemy(enemy, effect.amount, effect.hits || 1, { crit: true });
263:         }
264:         break;
265:       }
266:       case "damageIfBleed": {
267:         if (target?.alive && target.statuses.bleed > 0) {
268:           this.strikeEnemy(target, effect.amount, 1, { crit: true });
269:           this.log(`Bleeding target: +${effect.amount} bonus damage.`, "muted");
270:         }
271:         break;
272:       }
273:       case "block":
274:         player.block += effect.amount;
275:         this.log(`Gain ${effect.amount} Block.`, "good");
276:         break;
277:       case "overshield":
278:         player.overshield += effect.amount;
279:         this.log(`Gain ${effect.amount} Overshield.`, "good");
280:         break;
281:       case "status": {
282:         if (effect.target === "self") {
283:           if (effect.status === "crit") {
284:             combat.critBonus += effect.amount / 100;
285:             this.log(`+${effect.amount}% Crit this turn.`, "good");
286:           }
287:           break;
288:         }
289:         const targets = effect.target === "allEnemies" || allTargets ? this.aliveEnemies() : target ? [target] : [];
290:         for (const enemy of targets) {
291:           this.applyEnemyStatus(enemy, effect.status, effect.amount);
292:         }
293:         break;
294:       }
295:       case "multiplyStatus": {
296:         if (!target?.alive) break;
297:         if (effect.status === "book") {
298:           const stacks = target.statuses.book;
299:           if (stacks > 0) this.addBook(target, stacks);
300:         } else if (effect.status === "bleed") {
301:           target.statuses.bleed *= 2;
302:           this.log(`Bleed on ${target.name} doubles to ${target.statuses.bleed}.`, "good");
303:         }
304:         break;
305:       }
306:       case "draw":
307:         this.drawCards(effect.amount);
308:         this.log(`Draw ${effect.amount}.`, "muted");
309:         break;
310:       case "energy":
311:         combat.stamina += effect.amount;
312:         this.log(`Gain ${effect.amount} Stamina.`, "good");
313:         break;
314:       case "heal":
315:         player.hp = Math.min(player.maxHp, player.hp + effect.amount);
316:         this.log(`Heal ${effect.amount} HP.`, "good");
317:         break;
318:       case "loseHp":
319:         player.hp = Math.max(0, player.hp - effect.amount);
320:         this.log(`Lose ${effect.amount} HP.`, "bad");
321:         break;
322:       case "strength":
323:         player.strength += effect.amount;
324:         this.log(`Gain ${effect.amount} Strength.`, "good");
325:         break;
326:       case "summonMaxHp": {
327:         const taco = combat.taco;
328:         if (!taco) break;
329:         taco.maxHp += effect.amount;
330:         if (taco.alive) taco.hp += effect.amount;
331:         this.log(`Taco grows tougher. ${taco.hp}/${taco.maxHp} HP.`, "good");
332:         break;
333:       }
334:       case "summonHeal": {
335:         const taco = combat.taco;
336:         if (!taco || !taco.alive) {
337:           this.log("Taco is not here to heal.", "muted");
338:           break;
339:         }
340:         const before = taco.hp;
341:         taco.hp = Math.min(taco.maxHp, taco.hp + effect.amount);
342:         this.log(`Taco heals ${taco.hp - before} HP. ${taco.hp}/${taco.maxHp}.`, "good");
343:         break;
344:       }
345:       case "tacoBlock": {
346:         const taco = combat.taco;
347:         if (!taco || !taco.alive) break;
348:         taco.block += effect.amount;
349:         this.log(`Taco gains ${effect.amount} Block.`, "good");
350:         break;
351:       }
352:       case "tacoAttack": {
353:         const taco = combat.taco;
354:         if (!taco || !taco.alive) {
355:           this.log("Taco is not here. The card does nothing.", "muted");
356:           break;
357:         }
358:         if (target?.alive) this.tacoBite(target, effect.amount + taco.attack);
359:         break;
360:       }
361:       case "reviveTaco": {
362:         const taco = combat.taco;
363:         if (!taco) break;
364:         if (!taco.alive) {
365:           taco.alive = true;
366:           taco.hp = Math.min(taco.maxHp, effect.amount);
367:           taco.block = 0;
368:           taco.deathLogged = false;
369:           this.log(`Taco returns! ${taco.hp}/${taco.maxHp} HP.`, "good");
370:         } else {
371:           const before = taco.hp;
372:           taco.hp = Math.min(taco.maxHp, taco.hp + effect.heal);
373:           this.log(`Taco heals ${taco.hp - before} HP.`, "good");
374:         }
375:         break;
376:       }
377:       default:
378:         break;
379:     }
380:   },
381: 
382:   strikeEnemy(enemy, amount, hits = 1, { crit = false, ignoreBlock = false, useStrength = true, label = null } = {}) {
383:     if (!enemy?.alive) return 0;
384:     const combat = this.combat;
385:     const player = combat.player;
386:     let total = 0;
387:     let critCount = 0;
388:     for (let i = 0; i < hits; i += 1) {
389:       if (!enemy.alive) break;
390:       let damage = amount + (useStrength ? player.strength : 0);
391:       let didCrit = false;
392:       if (crit) {
393:         const critChance = clamp(player.crit + combat.critBonus, 0, 0.95);
394:         if (Math.random() < critChance) {
395:           damage *= player.critDamage;
396:           didCrit = true;
397:           critCount += 1;
398:           if (this.run.char === "roxy") {
399:             combat.critBonus += 0.08;
400:             this.log("Hot Streak: +8% Crit this turn.", "good");
401:           }
402:         }
403:       }
404:       if (enemy.statuses.vulnerable > 0) damage *= 1.5;
405:       if (player.weak > 0) damage *= 0.75;
406:       damage = Math.max(1, Math.round(damage));
407:       if (ignoreBlock) {
408:         enemy.hp -= damage;
409:         total += damage;
410:       } else {
411:         const absorbed = Math.min(enemy.block, damage);
412:         enemy.block -= absorbed;
413:         const through = damage - absorbed;
414:         enemy.hp -= through;
415:         total += through;
416:       }
417:       if (enemy.hp <= 0) {
418:         enemy.hp = 0;
419:         enemy.alive = false;
420:       }
421:     }
422:     const critText = critCount ? ` · ${critCount} CRIT` : "";
423:     this.log(`${label || CHARACTERS[this.run.char].name} hits ${enemy.name} for ${total}${hits > 1 ? ` (${hits} hits${critText})` : critText}.`, critCount ? "good" : "damage");
424:     this.afterEnemyDamaged(enemy);
425:     return total;
426:   },
427: 
428:   tacoBite(enemy, amount) {
429:     if (!enemy?.alive) return;
430:     const combat = this.combat;
431:     const taco = combat.taco;
432:     if (!taco?.alive) return;
433:     const damage = Math.max(1, amount);
434:     const absorbed = Math.min(enemy.block, damage);
435:     enemy.block -= absorbed;
436:     const through = damage - absorbed;
437:     enemy.hp -= through;
438:     if (enemy.hp <= 0) {
439:       enemy.hp = 0;
440:       enemy.alive = false;
441:     }
442:     this.log(`Taco bites ${enemy.name} for ${through}.`, "good");
443:     this.afterEnemyDamaged(enemy);
444:   },
445: 
446:   afterEnemyDamaged(enemy) {
447:     if (!enemy) return;
448:     if (enemy.hp <= 0 && enemy.alive) {
449:       enemy.hp = 0;
450:       enemy.alive = false;
451:     }
452:     if (!enemy.alive) {
453:       if (!enemy.defeatLogged) {
454:         enemy.defeatLogged = true;
455:         this.log(`${enemy.name} is defeated.`, "good");
456:       }
457:       return;
458:     }
459:     if (enemy.boss && !enemy.enraged && enemy.hp <= enemy.maxHp * 0.5) {
460:       enemy.enraged = true;
461:       enemy.strength += 3;
462:       enemy.block += 10;
463:       this.log(`${enemy.name} stops pretending. Second phase.`, "boss");
464:     }
465:   },
466: 
467:   addBook(enemy, amount, silent = false) {
468:     if (!enemy?.alive || amount <= 0) return;
469:     enemy.statuses.book += amount;
470:     if (!silent) this.log(`${enemy.name} gains ${amount} Book (${enemy.statuses.book}/10).`, "book");
471:     let guard = 0;
472:     while (enemy.statuses.book >= 10 && enemy.alive && guard < 20) {
473:       guard += 1;
474:       enemy.statuses.book -= 10;
475:       const damage = Math.ceil(enemy.maxHp * 0.15);
476:       enemy.hp -= damage;
477:       this.log(`OVERDUE! ${enemy.name} takes ${damage} damage — 15% max HP.`, "book");
478:       this.afterEnemyDamaged(enemy);
479:     }
480:   },
481: 
482:   applyEnemyStatus(enemy, status, amount) {
483:     if (!enemy?.alive) return;
484:     if (status === "book") {
485:       this.addBook(enemy, amount);
486:       return;
487:     }
488:     if (status in enemy.statuses) {
489:       enemy.statuses[status] += amount;
490:       this.log(`${enemy.name} gains ${amount} ${STATUS_INFO[status]?.name || status}.`, status === "bleed" ? "bleed" : "muted");
491:     }
492:   },
493: 
494:   applyPlayerStatus(status, amount) {
495:     const player = this.combat.player;
496:     if (status in player) {
497:       player[status] += amount;
498:       this.log(`You gain ${amount} ${STATUS_INFO[status]?.name || status}.`, "bad");
499:     }
500:   },
501: 
502:   finishVictory() {
503:     const combat = this.combat;
504:     if (!combat || combat.ended) return;
