520:   },
521: 
522:   endTurn() {
523:     const combat = this.combat;
524:     if (!combat || combat.ended || combat.phase !== "player") return;
525:     this.combat.hand.forEach((card) => this.combat.discardPile.push(card));
526:     this.combat.hand = [];
527:     this.combat.pendingCard = null;
528:     this.combat.critBonus = 0;
529:     combat.player.weak = Math.max(0, combat.player.weak - 1);
530:     combat.player.vulnerable = Math.max(0, combat.player.vulnerable - 1);
531:     this.log("You end your turn.", "turn");
532:     combat.phase = "enemy";
533:     this.runEnemyTurn();
534:   },
535: 
536:   runEnemyTurn() {
537:     const combat = this.combat;
538:     const actors = [...combat.enemies];
539:     for (const enemy of combat.enemies) enemy.taunt = false;
540:     for (const enemy of actors) {
541:       if (combat.ended) return;
542:       if (!enemy.alive) continue;
543:       enemy.block = 0;
544:       if (enemy.statuses.bleed > 0) {
545:         const bleed = enemy.statuses.bleed;
546:         enemy.hp -= bleed;
547:         this.log(`${enemy.name} bleeds for ${bleed}.`, "bleed");
548:         enemy.statuses.bleed = Math.max(0, enemy.statuses.bleed - 1);
549:         this.afterEnemyDamaged(enemy);
550:         if (!enemy.alive) continue;
551:       }
552:       const move = enemy.moves[enemy.pattern[enemy.moveIndex % enemy.pattern.length]];
553:       this.log(`${enemy.name}: ${move.name}.`, "enemy");
554:       this.executeEnemyMove(enemy, move);
555:       enemy.moveIndex += 1;
556:       enemy.statuses.weak = Math.max(0, enemy.statuses.weak - 1);
557:       enemy.statuses.vulnerable = Math.max(0, enemy.statuses.vulnerable - 1);
558:       if (combat.player.hp <= 0) {
559:         this.playerDefeated();
560:         return;
561:       }
562:       if (!this.aliveEnemies().length) {
563:         this.finishVictory();
564:         return;
565:       }
566:     }
567:     if (!this.aliveEnemies().length) {
568:       this.finishVictory();
569:       return;
570:     }
571:     if (combat.player.hp <= 0) {
572:       this.playerDefeated();
573:       return;
574:     }
575:     this.startPlayerTurn();
576:   },
577: 
578:   executeEnemyMove(enemy, move) {
579:     const combat = this.combat;
580:     if (move.block) {
581:       enemy.block += move.block;
582:       this.log(`${enemy.name} gains ${move.block} Block.`, "muted");
583:     }
584:     if (move.taunt) {
585:       enemy.taunt = true;
586:       this.log(`${enemy.name} taunts. Strike them or waste the turn.`, "bad");
587:     }
588:     if (move.strength) {
589:       enemy.strength += move.strength;
590:       this.log(`${enemy.name} gains ${move.strength} Strength.`, "bad");
591:     }
592:     if (move.strengthAll) {
593:       for (const ally of this.aliveEnemies()) ally.strength += move.strengthAll;
594:       this.log(`All enemies gain ${move.strengthAll} Strength.`, "bad");
595:     }
596:     if (move.heal) {
597:       enemy.hp = Math.min(enemy.maxHp, enemy.hp + move.heal);
598:       this.log(`${enemy.name} heals ${move.heal}.`, "bad");
599:     }
600:     if (move.healAll) {
601:       for (const ally of this.aliveEnemies()) ally.hp = Math.min(ally.maxHp, ally.hp + move.healAll);
602:       this.log(`All enemies heal ${move.healAll}.`, "bad");
603:     }
604:     if (move.summon) {
605:       if (combat.enemies.length >= 5) {
606:         enemy.block += 8;
607:         this.log("The room is too full. The summon becomes 8 Block.", "muted");
608:       } else {
609:         const summoned = this.createEnemy(move.summon);
610:         summoned.summoned = true;
611:         combat.enemies.push(summoned);
612:         this.log(`${enemy.name} summons ${summoned.name}.`, "bad");
613:       }
614:     }
615:     if (move.status) this.applyPlayerStatus(move.status.type, move.status.amount);
616:     if (move.status2) this.applyPlayerStatus(move.status2.type, move.status2.amount);
617: 
618:     if (move.dmg) {
619:       const hits = move.hits || 1;
620:       let totalToPlayer = 0;
621:       let totalToTaco = 0;
622:       let blocked = 0;
623:       for (let i = 0; i < hits; i += 1) {
624:         let raw = move.dmg + enemy.strength;
625:         if (enemy.statuses.weak > 0) raw *= 0.75;
626:         raw = Math.round(raw);
627:         if (move.aoe) {
628:           if (combat.taco?.alive) {
629:             const result = this.damageTaco(raw);
630:             totalToTaco += result.through;
631:             blocked += result.blocked;
632:           }
633:           if (combat.player.hp > 0) {
634:             const result = this.damagePlayer(raw);
635:             totalToPlayer += result.through;
636:             blocked += result.blocked;
637:           }
638:         } else if (combat.taco?.alive) {
639:           const result = this.damageTaco(raw);
640:           totalToTaco += result.through;
641:           blocked += result.blocked;
642:         } else {
643:           const result = this.damagePlayer(raw);
644:           totalToPlayer += result.through;
645:           blocked += result.blocked;
646:         }
647:         if (combat.player.hp <= 0) break;
648:       }
649:       const pieces = [];
650:       if (totalToTaco) pieces.push(`${totalToTaco} to Taco`);
651:       if (totalToPlayer) pieces.push(`${totalToPlayer} to you`);
652:       if (blocked) pieces.push(`${blocked} blocked`);
653:       if (!pieces.length) pieces.push("no damage through");
654:       this.log(`${move.name}: ${pieces.join(", ")}.`, totalToPlayer || totalToTaco ? "damage-in" : "muted");
655:       if (!combat.taco?.alive && combat.taco && !combat.taco.deathLogged) {
656:         combat.taco.deathLogged = true;
657:         this.log("Taco is down. You are on your own.", "bad");
658:       }
659:     }
660:     if (move.dmg && combat.thorns > 0 && (!combat.taco || !combat.taco.alive || move.aoe)) {
661:       enemy.hp -= combat.thorns;
662:       this.log(`Thorn Pin pricks ${enemy.name} for ${combat.thorns}.`, "good");
663:       this.afterEnemyDamaged(enemy);
664:     }
665:   },
666: 
667:   damagePlayer(raw) {
668:     const player = this.combat.player;
669:     let damage = raw;
670:     if (player.vulnerable > 0) damage = Math.round(damage * 1.5);
671:     const blocked = Math.min(player.block, damage);
672:     player.block -= blocked;
673:     let remaining = damage - blocked;
674:     const shielded = Math.min(player.overshield, remaining);
675:     player.overshield -= shielded;
676:     remaining -= shielded;
677:     player.hp = Math.max(0, player.hp - remaining);
678:     return { blocked, through: remaining };
679:   },
680: 
681:   damageTaco(raw) {
682:     const taco = this.combat.taco;
683:     let damage = raw;
684:     const blocked = Math.min(taco.block, damage);
685:     taco.block -= blocked;
686:     let remaining = damage - blocked;
687:     taco.hp = Math.max(0, taco.hp - remaining);
688:     if (taco.hp <= 0) {
689:       taco.alive = false;
690:       taco.hp = 0;
691:     }
692:     return { blocked, through: remaining };
693:   },
694: 
695:   startPlayerTurn() {
696:     const combat = this.combat;
697:     if (combat.ended) return;
698:     combat.turn += 1;
699:     combat.phase = "player";
700:     combat.player.block = 0;
701:     combat.critBonus = 0;
702:     if (combat.taco) combat.taco.block = 0;
703: 
704:     if (combat.player.bleed > 0) {
705:       const bleed = combat.player.bleed;
706:       combat.player.hp = Math.max(0, combat.player.hp - bleed);
707:       combat.player.bleed = Math.max(0, combat.player.bleed - 1);
708:       this.log(`You bleed for ${bleed}.`, "bleed");
709:       if (combat.player.hp <= 0) {
710:         this.playerDefeated();
711:         return;
712:       }
713:     }
714: 
715:     if (combat.taco?.alive) {
716:       const targets = this.aliveEnemies();
717:       if (targets.length) {
718:         const victim = pick(targets);
