import { Game } from "./js/game.js";
import { CHARACTER_IDS } from "./js/data/characters.js";
import { CARDS } from "./js/data/cards.js";

let failures = 0;
function check(cond, msg) {
  if (!cond) {
    failures += 1;
    console.log("FAIL:", msg);
  }
}

for (const id of CHARACTER_IDS) {
  const g = new Game(null);
  g.briefing = { charId: id, outfit: 0 };
  g.beginRun();
  check(g.run.deck.length === 3, `${id} starter deck is ${g.run.deck.length}, expected 3`);
  check(g.run.deck.every((c) => CARDS[c.key].rarity === "starter"), `${id} starter deck has non-starter cards`);
  console.log(id.padEnd(10), g.run.deck.map((c) => CARDS[c.key].name).join(", "));

  for (const mode of ["normal", "elite", "boss"]) {
    const want = g.rewardTakes(mode) + 2;
    for (let i = 0; i < 25; i += 1) {
      const cards = g.buildRewardCards(mode);
      check(cards.length === want, `${id}/${mode} offered ${cards.length}, expected ${want}`);
      check(new Set(cards.map((c) => c.key)).size === cards.length, `${id}/${mode} has duplicate offers`);
      check(cards.every((c) => CARDS[c.key].rarity !== "starter"), `${id}/${mode} offered a starter card`);
    }
  }
}

// Multi-card draft: elite should take 2 and advance after the second pick.
{
  const g = new Game(null);
  g.briefing = { charId: "roxy", outfit: 0 };
  g.beginRun();
  const node = g.run.map.nodes.find((n) => n.row === 1);
  g.pending = {
    reward: {
      node,
      gold: 10,
      mode: "elite",
      takes: g.rewardTakes("elite"),
      picked: 0,
      done: false,
      cards: g.buildRewardCards("elite"),
      elite: true,
      boss: false,
    },
  };
  g.screen = "reward";
  const before = g.run.deck.length;
  g.chooseReward(0);
  check(g.run.deck.length === before + 1, "first elite pick did not add a card");
  check(g.screen === "reward", "elite reward advanced after only one pick");
  g.chooseReward(1);
  check(g.run.deck.length === before + 2, "second elite pick did not add a card");
  check(g.pending === null && g.screen === "map", "elite reward did not advance after two picks");
}

// Boss should take 3.
{
  const g = new Game(null);
  g.briefing = { charId: "brittany", outfit: 0 };
  g.beginRun();
  const node = g.run.map.nodes.find((n) => n.row === 1);
  g.pending = {
    reward: {
      node,
      gold: 10,
      mode: "boss",
      takes: g.rewardTakes("boss"),
      picked: 0,
      done: false,
      cards: g.buildRewardCards("boss"),
      elite: false,
      boss: true,
    },
  };
  g.screen = "reward";
  const before = g.run.deck.length;
  g.chooseReward(0);
  g.chooseReward(1);
  check(g.screen === "reward", "boss reward advanced after two picks");
  g.chooseReward(2);
  check(g.run.deck.length === before + 3, "boss reward did not add three cards");
  check(g.pending === null && g.screen === "map", "boss reward did not advance after three picks");
}

console.log(failures ? `${failures} FAILURES` : "All checks passed.");
process.exit(failures ? 1 : 0);

import { Game } from "./js/game.js";
import { CHARACTER_IDS } from "./js/data/characters.js";
import { CARDS } from "./js/data/cards.js";
import { NORMAL_ENCOUNTERS } from "./js/data/enemies.js";

function simulate(charId, keys, deck = null) {
  const g = new Game(null);
  g.briefing = { charId, outfit: 0 };
  g.beginRun();
  if (deck) g.run.deck = deck.map((key) => g.makeCard(key));
  const node = g.run.map.nodes.find((n) => n.row === 1);
  g.beginCombat(node, keys);
  const combat = g.combat;
  let guard = 0;
  while (!combat.ended && guard < 200) {
    guard += 1;
    if (combat.phase !== "player") break;
    let played = false;
    for (let i = 0; i < 12; i += 1) {
      const alive = combat.enemies.filter((e) => e.alive);
      if (!alive.length) break;
      const playable = combat.hand.filter((c) => CARDS[c.key].cost <= combat.stamina);
      if (!playable.length) break;
      // Prefer attacks, then block/skills.
      playable.sort((a, b) => {
        const ca = CARDS[a.key];
        const cb = CARDS[b.key];
        return (cb.type === "attack") - (ca.type === "attack");
      });
      const card = playable[0];
      g.playCard(card.uid, alive[0].uid);
      played = true;
      if (combat.ended) break;
    }
    if (combat.ended) break;
    if (!played || combat.hand.every((c) => CARDS[c.key].cost > combat.stamina)) {
      g.endTurn();
    }
    if (combat.phase === "player" && combat.hand.every((c) => CARDS[c.key].cost > combat.stamina)) {
      g.endTurn();
    }
  }
  return { won: combat.phase === "victory", turns: combat.turn, hp: combat.player.hp };
}

for (const id of CHARACTER_IDS) {
  let wins = 0;
  let total = 0;
  let hpLeft = 0;
  for (const keys of NORMAL_ENCOUNTERS[1]) {
    for (let i = 0; i < 60; i += 1) {
      const result = simulate(id, keys);
      total += 1;
      if (result.won) {
        wins += 1;
        hpLeft += result.hp;
      }
    }
  }
  console.log(`${id.padEnd(10)} starter vs act-1 normals: ${wins}/${total} wins, avg HP left ${wins ? Math.round(hpLeft / wins) : 0}`);
}

