import { Game } from "./js/game.js";
import { CARDS } from "./js/data/cards.js";

const g = new Game(null);
g.briefing = { charId: "roxy", outfit: 0 };
g.beginRun();
const node = g.run.map.nodes.find((n) => n.row === 1);
g.beginCombat(node, ["page_mite"]);
let guard = 0;
while (!g.combat.ended && guard < 100) {
  guard += 1;
  const c = g.combat;
  const alive = c.enemies.filter((e) => e.alive);
  if (!alive.length) break;
  const playable = c.hand.filter((card) => CARDS[card.key].cost <= c.stamina);
  if (playable.length) {
    g.playCard(playable[0].uid, alive[0].uid);
  } else {
    g.endTurn();
  }
}
console.log("phase:", g.combat.phase, "screen:", g.screen);
console.log("reward:", {
  takes: g.pending?.reward?.takes,
  offers: g.pending?.reward?.cards?.length,
  picked: g.pending?.reward?.picked,
  deck: g.run.deck.length,
});
const before = g.run.deck.length;
let picks = 0;
while (g.pending?.reward && !g.pending.reward.done && picks < 5) {
  picks += 1;
  g.chooseReward(picks - 1);
}
console.log("after draft:", { screen: g.screen, deck: g.run.deck.length, expected: before + g.pending?.reward?.takes || "advanced" });

